syntax:
int pid = fork();
/* ... error handling ... */
if (pid == 0) { 
  // Child process
  execve(filename, argv, envp);
  // execve only returns on error
} else { 
  // Parent process
  // ... wait for child (if foreground) ...
}

code_example:
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
int main() {
  pid_t pid = fork();
  if (pid < 0) {
    perror("fork failed");
    exit(1);
  }
  else if (pid == 0) {
    char *args[] = {"ls", "-l", NULL};
    execve("/bin/ls", args, NULL);
    perror("execve failed"); //only reached if execve fails
    exit(1);
  }
  else {
    printf("Child process created with PID: %d\n", pid);
    wait(NULL); //wait for child to finish
  }
  return 0;
}
